  "d.109szp9": "Պինդ ռելիեֆ կամ կառույցներ, որոնց հետ կարելի է բախվել։",
  "d.10azxrl": "Երեք արևային շառավիղ ֆոտոսֆերայից վեր։ Ստվերը կյանք է՝ հարթակի վահանը, գիսաստղը, խոշոր կորպուսները։ Բռնկումներ լինում են մի քանի րոպեն մեկ։",
  "d.10wlatv": "Ընտրովի գույնը, որի ամենապայծառ ալիքը 0x40-ից ցածր է, ընդունվում է որպես STOCK, ուստի վահանը երբեք անտեսանելի չի դառնում։",
  "d.11cuwtu": "ՀՐԹԻՌՆԵՐ",
  "d.11jyj1n": "Էսմինեց, որը կառուցված է միջին ողնաշարային ռելսոտրոնի շուրջ՝ լազերային աշտարակներով և տասնվեց հրթիռային բջիջներով։",
  "d.11phsqq": "Խաղը հրատարակում է հրատարակիչ, որը թույլ է տալիս 100% ԱԻ-ով ստեղծված բովանդակություն։",
  "d.11zjijr": "Զենքերը կարելի է տեղակայել և ետ քաշել (ետ քաշված զենքերը թաքնված են), և նավերն այլևս ծուխ չեն թողնում իրենց հետևից։",
  "d.11zq7hg": "Տեսքը՝ ֆիզիկապես լուսավորված օդաչուի խցիկներ, դասակարգված աստղեր, օղակավոր գազային հսկա, գալակտիկայի և միգամածության հետնապատկեր, շարժիչների բոցեր և նավիգացիոն լույսեր. 0.1.0-ի խաղային զգացողությունը կողպված է։",
  "d.12zyt91": "ANVIL՝ խաղի ցանկի անգարի պատկերը (կորպուսը՝ ինչպես կառուցված է 0.3.0-ի և հետագա տարբերակների համար. բնօրինակ չափը՝ 256 x 128)։ Խաղային նկար, տարբերակ 0.6.1",
  "d.13cb0px": "Թշնամիներ քաղաքի վերևում՝ շարժիչների բոցերով (GLASGOW)։ Խաղային նկար, տարբերակ 0.5.3",
  "d.1436q76": "0.5.1 տարբերակը սառեցված է՝ սպառազինության հանգույցների նստատեղեր, վեց հրթիռանոց համազարկներ և ANVIL-ի անգար, որը արձակում է 10 NEEDLE։",
